-- =============================================================================
-- 472 — LE CAHIER D'EXERCICES DE 5E (partie 1)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/5e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 472 --niveau 5e --fichiers allemand.n1,anglais.n1,anglais.n2 --suffixe 1 > supabase/contenu/472_exercices_5e_1.sql
--
-- 75 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   allemand.n1              9 exercices · 3 chapitres
--   anglais.n1              33 exercices · 11 chapitres
--   anglais.n2              33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('f9ccd6ca-42ef-5703-8abd-90b26c93cf77'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Premier jour à Hambourg","competence":"comprendre-langue","situation":"Anna, une jeune Française, arrive dans une classe d’échange en Allemagne. Elle discute avec Ben, son voisin de table. Lis leur conversation et retrouve ce qu’ils se disent.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Anna et Ben se présentent","participants":[{"nom":"Anna","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Anna","texte":"Hallo! Ich heiße Anna. Wie heißt du?"},{"qui":"Ben","texte":"Hallo Anna! Ich bin Ben. Ich komme aus Berlin. Und du?"},{"qui":"Anna","texte":"Ich komme aus Frankreich. Ich wohne in Lyon. Ich bin 13 Jahre alt."}]}],"questions":[{"enonce":"Touche la ville où habite Anna.","aide":"Cherche la phrase « Ich wohne in … ».","type":"zone","document":"sms","multiple":false},{"enonce":"Touche le nombre qui donne l’âge d’Anna.","aide":"Cherche « Jahre alt ».","type":"zone","document":"sms","multiple":false},{"enonce":"Que demande Anna à Ben avec « Wie heißt du ? »","aide":"Anna vient de dire son nom, juste avant.","type":"choix","options":[{"id":"a","texte":"Comment tu t’appelles ?"},{"id":"b","texte":"Quel âge as-tu aujourd’hui ?"},{"id":"c","texte":"De quelle ville viens-tu ?"},{"id":"d","texte":"Où est-ce que tu habites ?"}],"multiple":false},{"enonce":"Complète la phrase de Ben.","aide":"Ben dit d’où il vient.","type":"trous","segments":["Ich komme ",0," Berlin."],"banque":["in","bin","du","aus"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25"]},"explication":"**Lyon** : *Ich wohne in Lyon* = « j’habite à Lyon »."},{"cle":{"type":"zone","ids":["m28"]},"explication":"**13** : *Ich bin 13 Jahre alt* = « j’ai 13 ans »."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Wie heißt du ?** = « Comment tu t’appelles ? »"},{"cle":{"type":"trous","trous":[["aus"]]},"affichage":"aus","explication":"**Ich komme aus Berlin** = « je viens de Berlin ». *aus* veut dire « de, en venant de »."}]$ex$::jsonb),
  ('f9ccd6ca-42ef-5703-8abd-90b26c93cf77'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Au revoir, Herr Braun !","competence":"manier-langue","situation":"Tim croise un voisin adulte, Herr Braun. Il ne doit pas se tromper de registre : tu ne dis pas « tu » à un adulte que tu ne connais pas. Lis l’échange et classe les formules.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Tim et Herr Braun","participants":[{"nom":"Tim","emoji":"👦","cote":"gauche"},{"nom":"Herr Braun","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Tim","texte":"Guten Tag. Wie heißen Sie?"},{"qui":"Herr Braun","texte":"Ich heiße Braun. Und wie heißt du?"},{"qui":"Tim","texte":"Ich bin Tim. Auf Wiedersehen, Herr Braun!"}]}],"questions":[{"enonce":"Touche le mot par lequel Tim vouvoie Herr Braun.","aide":"C’est le « vous » de politesse, écrit avec une majuscule.","type":"zone","document":"sms","multiple":false},{"enonce":"Pourquoi « Sie » prend-il une majuscule au milieu de la phrase ?","aide":"Compare avec « du », qui s’écrit en minuscule.","type":"choix","options":[{"id":"a","texte":"C’est le début d’une nouvelle phrase du dialogue"},{"id":"b","texte":"C’est un nom propre, comme le prénom d’une personne"},{"id":"c","texte":"C’est le « vous » de politesse, toujours en majuscule"},{"id":"d","texte":"C’est un nom commun, comme tous les noms allemands"}],"multiple":false},{"enonce":"Classe ces formules selon le registre.","aide":"Dis-toi : « tu » = familier, « Sie » = poli.","type":"categories","categories":[{"id":"c0","texte":"Familier"},{"id":"c1","texte":"Poli"}],"items":[{"id":"i0","texte":"Wie heißt du ?"},{"id":"i1","texte":"Auf Wiedersehen"},{"id":"i2","texte":"Tschüss"},{"id":"i3","texte":"Wie heißen Sie ?"},{"id":"i4","texte":"Hallo"}]},{"enonce":"Tim dit au revoir poliment à un adulte. Complète.","aide":"Cherche la formule polie pour partir, dans le dialogue.","type":"trous","segments":[0," , Herr Braun !"],"banque":["Auf Wiedersehen","Hallo","Guten Abend","Tschüss"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**Sie** est le « vous » de politesse : Tim vouvoie un adulte inconnu."},{"cle":{"type":"choix","ids":["c"]},"explication":"*Sie* (vous de politesse) s’écrit **toujours avec une majuscule**, même au milieu d’une phrase. *du* (tu) reste en minuscule."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c0"}},"explication":"*Hallo*, *Tschüss* et *Wie heißt du ?* sont **familiers**. *Auf Wiedersehen* et *Wie heißen Sie ?* sont **polis**."},{"cle":{"type":"trous","trous":[["auf wiedersehen"]]},"affichage":"Auf Wiedersehen","explication":"**Auf Wiedersehen** est la formule polie pour prendre congé d’un adulte ; *Tschüss* est familier."}]$ex$::jsonb),
  ('f9ccd6ca-42ef-5703-8abd-90b26c93cf77'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les nombres à l’envers","competence":"lire-tableau","situation":"L’école de Mia organise un tournoi de tennis. La liste des inscrits donne l’âge de chacun… en lettres. Pour la lire, il faut se rappeler que l’allemand dit les nombres « à l’envers » : l’unité d’abord, puis la dizaine.","documents":[{"id":"club","type":"tableau","titre":"Der Tennisclub","colonnes":["Name","Alter"],"lignes":[["Lena","einundzwanzig"],["Herr Koch","vierundsechzig"],["Anja","fünfundzwanzig"],["Paul","siebenundzwanzig"],["Frau Hahn","achtundsechzig"]],"enteteLignes":false,"source":"Liste écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Mia et Jonas","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Jonas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Ich bin 13 Jahre alt. Und du?"},{"qui":"Jonas","texte":"Ich habe 13 Jahre."}]}],"questions":[{"enonce":"Quel âge a Herr Koch ?","aide":"Vierundsechzig = quatre-et-soixante.","type":"nombre","unite":"ans"},{"enonce":"Touche l’âge de la personne la plus âgée du club.","aide":"Compare 64 et 68 : il faut déchiffrer chaque nombre.","type":"zone","document":"club","multiple":false},{"enonce":"Associe chaque nombre allemand à son écriture en chiffres.","aide":"Unité + und + dizaine : fünf-und-zwanzig = cinq-et-vingt.","type":"association","gauche":[{"id":"g0","texte":"einundzwanzig"},{"id":"g1","texte":"fünfundzwanzig"},{"id":"g2","texte":"siebenundzwanzig"},{"id":"g3","texte":"achtundsechzig"}],"droite":[{"id":"d0","texte":"68"},{"id":"d1","texte":"25"},{"id":"d2","texte":"21"},{"id":"d3","texte":"27"}]},{"enonce":"Touche le mot qui est une faute de débutant dans la réponse de Jonas.","aide":"En allemand, on ne « possède » pas son âge.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète la phrase d’Anja.","aide":"Reprends la phrase de Mia.","type":"trous","segments":["Ich ",0," fünfundzwanzig Jahre alt."],"banque":["bin","habe","bist","hat"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":64,"tolerance":0},"affichage":"64 ans","explication":"*vier-und-sechzig* : quatre et soixante, donc **64**."},{"cle":{"type":"zone","ids":["r4c1"]},"explication":"**achtundsechzig** = huit et soixante = 68, c’est plus que 64 (Herr Koch) : Frau Hahn est la plus âgée."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"On lit à l’envers : **21**, **25**, **27**, **68**."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**habe** est faux : en allemand on **est** âgé de treize ans (*Ich bin 13 Jahre alt*), on n’en a pas."},{"cle":{"type":"trous","trous":[["bin"]]},"affichage":"bin","explication":"**Ich bin fünfundzwanzig Jahre alt** : on utilise *sein* (« être »), jamais *haben*."}]$ex$::jsonb),
  ('ec3f56f3-71ee-50ec-afa9-c7c87ace6ca7'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dans ma chambre : der, die, das","competence":"observer-schema","situation":"Lukas dessine trois objets de sa chambre et écrit leur nom avec leur article. Les trois noms n’ont pas le même genre.","documents":[{"id":"chambre","type":"schema","titre":"Lukas’ Zimmer","largeur":320,"hauteur":160,"elements":[{"forme":"rect","x":15,"y":15,"l":90,"h":120,"arrondi":10,"id":"z1","zone":true,"teinte":"sable","motif":"clair"},{"forme":"emoji","x":60,"y":60,"emoji":"💡","taille":36},{"forme":"texte","x":60,"y":118,"texte":"die Lampe","ancre":"milieu"},{"forme":"rect","x":115,"y":15,"l":90,"h":120,"arrondi":10,"id":"z2","zone":true,"teinte":"sable","motif":"clair"},{"forme":"emoji","x":160,"y":60,"emoji":"🐕","taille":36},{"forme":"texte","x":160,"y":118,"texte":"der Hund","ancre":"milieu"},{"forme":"rect","x":215,"y":15,"l":90,"h":120,"arrondi":10,"id":"z3","zone":true,"teinte":"sable","motif":"clair"},{"forme":"emoji","x":260,"y":60,"emoji":"📖","taille":36},{"forme":"texte","x":260,"y":118,"texte":"das Buch","ancre":"milieu"}],"source":"Dessin écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’objet dont l’article est « die ».","aide":"Lis l’article écrit sous chaque dessin.","type":"zone","document":"chambre","multiple":false},{"enonce":"Classe ces noms selon leur genre.","aide":"Masculin = der, féminin = die, neutre = das.","type":"categories","categories":[{"id":"c0","texte":"Masculin"},{"id":"c1","texte":"Féminin"},{"id":"c2","texte":"Neutre"}],"items":[{"id":"i0","texte":"die Schule"},{"id":"i1","texte":"der Freund"},{"id":"i2","texte":"das Haus"},{"id":"i3","texte":"das Mädchen"},{"id":"i4","texte":"der Tisch"}]},{"enonce":"Complète : « C’est une lampe. »","aide":"Lampe est féminin : quel article indéfini va avec le féminin ?","type":"trous","segments":["Das ist ",0," Lampe."],"banque":["ein","eine","der","einen"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**die Lampe** : « die » est l’article défini féminin."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c2","i4":"c0"}},"explication":"*der Tisch* et *der Freund* sont masculins, *die Schule* est féminin, *das Haus* et *das Mädchen* sont neutres (**das Mädchen**, la jeune fille, est neutre !)."},{"cle":{"type":"trous","trous":[["eine"]]},"affichage":"eine","explication":"**Das ist eine Lampe.** L’article indéfini féminin est *eine*."}]$ex$::jsonb),
  ('ec3f56f3-71ee-50ec-afa9-c7c87ace6ca7'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Je vois… : le masculin change","competence":"manier-langue","situation":"Léa et Tom jouent à « Je vois… » devant une image. À chaque tour, l’un nomme ce qu’il voit. Regarde bien la forme de l’article : elle change pour un seul genre.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Le jeu « Ich sehe… »","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Ich sehe einen Hund."},{"qui":"Tom","texte":"Ich sehe eine Lampe."},{"qui":"Léa","texte":"Ich sehe ein Haus."},{"qui":"Tom","texte":"Ich sehe einen Tisch."}]}],"questions":[{"enonce":"Touche les deux articles qui prennent la forme spéciale de l’accusatif masculin.","aide":"Der Hund et der Tisch sont masculins.","type":"zone","document":"sms","multiple":true},{"enonce":"Remets en ordre : « Le chien voit l’homme. » La phrase commence par Der Hund.","aide":"Sujet, verbe, complément.","type":"ordre","items":[{"id":"a","texte":"den Mann"},{"id":"b","texte":"sieht"},{"id":"c","texte":"Der Hund"}]},{"enonce":"Que signifie « Den Hund sieht der Mann » ?","aide":"Regarde qui est à l’accusatif : den ou der ?","type":"choix","options":[{"id":"a","texte":"L’homme voit le chien"},{"id":"b","texte":"Le chien et l’homme voient la maison"},{"id":"c","texte":"Le chien voit l’homme"},{"id":"d","texte":"L’homme cherche le chien"}],"multiple":false},{"enonce":"Complète : « Je vois l’homme. »","aide":"Mann est masculin et COD.","type":"trous","segments":["Ich sehe ",0," Mann."],"banque":["die","der","das","den"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m14"]},"explication":"**einen** (deux fois) : devant un nom masculin COD, *ein* devient *einen*. Féminin et neutre ne changent pas."},{"cle":{"type":"ordre","ids":["c","b","a"]},"explication":"**Der Hund sieht den Mann.** *Der Hund* est le sujet (nominatif), *den Mann* le COD (accusatif)."},{"cle":{"type":"choix","ids":["a"]},"explication":"*Den Hund* est à l’accusatif (COD) : c’est le chien qui est vu. **L’homme voit le chien.** L’ordre des mots a changé, pas le sens."},{"cle":{"type":"trous","trous":[["den"]]},"affichage":"den","explication":"**Ich sehe den Mann.** Au masculin, *der* devient *den* à l’accusatif."}]$ex$::jsonb),
  ('ec3f56f3-71ee-50ec-afa9-c7c87ace6ca7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Qui voit quoi ? Lire les articles","competence":"analyser-texte","situation":"Une légende sous un dessin décrit trois scènes. Pour savoir qui voit quoi, il faut repérer les articles : seul le masculin change à l’accusatif.","documents":[{"id":"legende","type":"texte","genre":"article","titre":"Sous le dessin","blocs":["Der Mann sieht den Hund.","Das Mädchen sieht die Lampe.","Der Freund sieht das Haus."],"source":"Légende écrite pour l’exercice"},{"id":"cas","type":"tableau","titre":"Nominatif et accusatif","colonnes":["Genre","Nominatif","Accusatif"],"lignes":[["Masculin","der / ein","?"],["Féminin","die / eine","die / eine"],["Neutre","das / ein","das / ein"],["Pluriel","die","die"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le seul article de ces trois phrases qui a changé de forme à l’accusatif.","aide":"Cherche l’article masculin qui n’est pas « der ».","type":"zone","document":"legende","multiple":false},{"enonce":"Classe ces groupes du texte : sujet ou COD ?","aide":"Le sujet fait l’action ; le COD la subit. Le groupe placé avant le verbe est le sujet.","type":"categories","categories":[{"id":"c0","texte":"Sujet (nominatif)"},{"id":"c1","texte":"COD (accusatif)"}],"items":[{"id":"i0","texte":"Der Mann"},{"id":"i1","texte":"den Hund"},{"id":"i2","texte":"das Haus"},{"id":"i3","texte":"die Lampe"},{"id":"i4","texte":"Das Mädchen"},{"id":"i5","texte":"der Freund"}]},{"enonce":"Quel article faut-il écrire dans la case « ? » du tableau, au masculin à l’accusatif (article défini) ?","aide":"Regarde la phrase « Der Mann sieht … Hund ».","type":"texte","placeholder":"l’article"},{"enonce":"Que signifie « Das Haus sieht der Freund » ?","aide":"Das Haus est neutre : sa forme ne change pas. Mais « der Freund » est au nominatif, pas à l’accusatif.","type":"choix","options":[{"id":"a","texte":"L’ami habite la maison"},{"id":"b","texte":"La maison de l’ami est belle"},{"id":"c","texte":"La maison voit l’ami"},{"id":"d","texte":"L’ami voit la maison"}],"multiple":false},{"enonce":"Associe chaque phrase française à sa traduction allemande.","aide":"Cherche d’abord le groupe au nominatif : le sujet.","type":"association","gauche":[{"id":"g0","texte":"Le chien voit l’homme"},{"id":"g1","texte":"L’homme voit le chien"},{"id":"g2","texte":"La jeune fille voit la lampe"}],"droite":[{"id":"d0","texte":"Der Mann sieht den Hund"},{"id":"d1","texte":"Das Mädchen sieht die Lampe"},{"id":"d2","texte":"Der Hund sieht den Mann"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**den** est l’accusatif de *der*. Dans *die Lampe* et *das Haus*, l’article ne change pas."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1","i4":"c0","i5":"c0"}},"explication":"Dans chaque phrase, le groupe avant le verbe est le sujet, celui après est le COD."},{"cle":{"type":"texte","acceptes":["den"]},"affichage":"den","explication":"Le masculin est le seul genre qui change : **der → den**."},{"cle":{"type":"choix","ids":["d"]},"explication":"**L’ami voit la maison.** *Der Freund* est au nominatif (sinon on aurait *den Freund*) : c’est lui le sujet, même placé en fin de phrase."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Le sujet reste *der* au masculin ; le COD masculin devient *den*."}]$ex$::jsonb),
  ('7e448107-365b-5ddb-acd8-5abfa8712cf3'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Jouer au football : le verbe change","competence":"manier-langue","situation":"Pour le tournoi de football, Mila remplit la fiche de conjugaison de *spielen* (jouer). Deux cases sont restées vides. Aide-la.","documents":[{"id":"conj","type":"tableau","titre":"spielen (jouer)","colonnes":["Personne","spielen"],"lignes":[["ich","spiele"],["du","?"],["er / sie / es","spielt"],["wir","spielen"],["ihr","?"],["sie / Sie","spielen"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Quelle forme faut-il écrire à la place du « ? » de la ligne « du » ?","aide":"Avec « du », la terminaison est -st.","type":"texte","placeholder":"du …"},{"enonce":"Quelle forme faut-il écrire à la place du « ? » de la ligne « ihr » ?","aide":"Avec « ihr », la terminaison est la même que pour « er ».","type":"texte","placeholder":"ihr …"},{"enonce":"Complète la phrase.","aide":"Regarde les lignes « wir » et « sie » (Lena) du tableau.","type":"trous","segments":["Wir ",0," Fußball und Lena ",1," Tennis."],"banque":["spielst","spiele","spielt","spielen"]},{"enonce":"Associe chaque pronom à la terminaison du verbe régulier.","aide":"Repère la fin de chaque forme du tableau.","type":"association","gauche":[{"id":"g0","texte":"ich"},{"id":"g1","texte":"du"},{"id":"g2","texte":"er / sie / es"},{"id":"g3","texte":"wir"}],"droite":[{"id":"d0","texte":"-st"},{"id":"d1","texte":"-t"},{"id":"d2","texte":"-e"},{"id":"d3","texte":"-en"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"texte","acceptes":["spielst"]},"affichage":"spielst","explication":"**du spielst** : on retire -en de l’infinitif et on ajoute **-st**."},{"cle":{"type":"texte","acceptes":["spielt"]},"affichage":"spielt","explication":"**ihr spielt** : la terminaison **-t** sert pour *er / sie / es* et pour *ihr*."},{"cle":{"type":"trous","trous":[["spielen"],["spielt"]]},"affichage":"spielen · spielt","explication":"**Wir spielen** (-en) et **Lena spielt** (-t)."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"**ich -e**, **du -st**, **er -t**, **wir -en**."}]$ex$::jsonb),
  ('7e448107-365b-5ddb-acd8-5abfa8712cf3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le verbe reste en deuxième position","competence":"manier-langue","situation":"Lena, Tom et Jonas parlent de leurs sorties. Leurs phrases n’ont pas la même forme, mais le verbe garde toujours la même place.","documents":[{"id":"saetze","type":"texte","genre":"article","titre":"Drei Sätze","blocs":["Ich gehe heute ins Kino.","Heute geht Lena ins Kino.","Ins Kino geht Tom heute."],"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche le verbe conjugué dans chacune des trois phrases.","aide":"Il y en a trois : un dans chaque phrase, toujours en deuxième position.","type":"zone","document":"saetze","multiple":true},{"enonce":"Dans la deuxième phrase, touche le sujet du verbe.","aide":"Qui va au cinéma ? Attention : le sujet est après le verbe.","type":"zone","document":"saetze","multiple":false},{"enonce":"Remets en ordre : « Aujourd’hui, Tom joue au football. » La phrase commence par Heute.","aide":"Le verbe doit rester en deuxième position.","type":"ordre","items":[{"id":"a","texte":"spielt"},{"id":"b","texte":"Tom"},{"id":"c","texte":"Fußball"},{"id":"d","texte":"Heute"}]},{"enonce":"Complète : « Anna va au cinéma aujourd’hui. »","aide":"Anna correspond à « sie » (elle).","type":"trous","segments":["Ins Kino ",0," Anna heute."],"banque":["geht","gehst","gehen","gehe"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m6","m12"]},"explication":"**gehe**, **geht**, **geht** : dans chaque phrase, le verbe est le deuxième élément."},{"cle":{"type":"zone","ids":["m7"]},"explication":"**Lena** est le sujet : après « Heute », le sujet passe derrière le verbe (inversion)."},{"cle":{"type":"ordre","ids":["d","a","b","c"]},"explication":"**Heute spielt Tom Fußball.** « Heute » est en première position, le verbe en deuxième, puis le sujet."},{"cle":{"type":"trous","trous":[["geht"]]},"affichage":"geht","explication":"**Ins Kino geht Anna heute.** *Anna* = sie : terminaison -t, et le verbe reste en deuxième position."}]$ex$::jsonb),
  ('7e448107-365b-5ddb-acd8-5abfa8712cf3'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un message pour Mia","competence":"analyser-texte","situation":"Jonas écrit à Mia pour l’inviter à jouer. Son message contient une question fermée, une question ouverte et une phrase où le sujet passe derrière le verbe. Un tableau t’aide pour *sein* et *haben*.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Ein Brief an Mia","blocs":["Hallo Mia!","Ich bin Jonas und ich wohne in Berlin. Heute spiele ich Fußball. Spielst du Tennis? Wann kommst du?","Tschüss, Jonas"],"source":"Lettre écrite pour l’exercice"},{"id":"verbes","type":"tableau","titre":"sein et haben","colonnes":["Personne","sein (être)","haben (avoir)"],"lignes":[["ich","bin","habe"],["du","bist","hast"],["er / sie / es","ist","hat"],["wir","sind","haben"],["ihr","?","habt"],["sie / Sie","sind","haben"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui ouvre la question fermée (oui / non).","aide":"Dans une question fermée, le verbe est en première position.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche le mot interrogatif qui veut dire « quand ».","aide":"C’est le premier mot d’une question ouverte.","type":"zone","document":"lettre","multiple":false},{"enonce":"Dans « Heute spiele ich Fußball », pourquoi « ich » se place-t-il après le verbe ?","aide":"Compte les éléments : Heute est le premier.","type":"choix","options":[{"id":"a","texte":"C’est une question et non une phrase déclarative"},{"id":"b","texte":"Le verbe reste en deuxième position après « Heute »"},{"id":"c","texte":"Un pronom se place toujours après le verbe"},{"id":"d","texte":"Le verbe doit toujours suivre le complément de temps"}],"multiple":false},{"enonce":"Quelle forme de *sein* faut-il écrire dans la case « ? » de la ligne « ihr » ?","aide":"Ce n’est ni « sind » ni « bist ».","type":"texte","placeholder":"ihr …"},{"enonce":"Complète la phrase avec *sein* et *haben*.","aide":"Mia = sie (elle) : troisième personne du singulier.","type":"trous","segments":["Mia ",0," 12 Jahre alt und sie ",1," einen Hund."],"banque":["habe","hat","ist","bin"]}]}$ex$::jsonb,
