e"}],"items":[{"id":"i0","texte":"He plays ___ guitar."},{"id":"i1","texte":"It takes ___ hour."},{"id":"i2","texte":"___ sun is hot."},{"id":"i3","texte":"We have ___ breakfast at seven."},{"id":"i4","texte":"She is ___ dentist."},{"id":"i5","texte":"I like ___ dogs."}]},{"enonce":"Remets en ordre : « Il est le meilleur joueur. » La phrase commence par He.","aide":"Le superlatif s’emploie avec the.","type":"ordre","items":[{"id":"a","texte":"best"},{"id":"b","texte":"the"},{"id":"c","texte":"is"},{"id":"d","texte":"player"},{"id":"e","texte":"He"}]}]}$ex$::jsonb,
