   $ex${"titre":"Le règlement du collège","competence":"comprendre-langue","situation":"Hugo arrive dans un collège anglais. À l’entrée, une affiche rappelle trois règles.","documents":[{"id":"regles","type":"fiche","modele":"panneau","entete":"School rules","emoji":"📋","lignes":[{"texte":"You must wear your uniform.","id":"z1"},{"texte":"You mustn’t run in the corridors.","id":"z2"},{"texte":"You don’t have to bring a pen: we have pens.","id":"z3"}],"pied":"Thank you!","teinte":"violet","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la règle qui dit que quelque chose est **interdit**.","aide":"Cherche la forme négative de must.","type":"zone","document":"regles","multiple":false},{"enonce":"Associe chaque forme à son sens.","aide":"Mustn’t et don’t have to ne veulent pas dire la même chose.","type":"association","gauche":[{"id":"g0","texte":"You must…"},{"id":"g1","texte":"You mustn’t…"},{"id":"g2","texte":"You don’t have to…"}],"droite":[{"id":"d0","texte":"c’est interdit"},{"id":"d1","texte":"ce n’est pas obligatoire"},{"id":"d2","texte":"c’est obligatoire"}]},{"enonce":"Hugo a oublié son stylo. D’après l’affiche, que se passe-t-il ?","aide":"Regarde la troisième règle.","type":"choix","options":[{"id":"a","texte":"Il est puni, car c’est interdit d’oublier son stylo"},{"id":"b","texte":"Il doit rentrer chez lui, car c’est obligatoire"},{"id":"c","texte":"Il doit en acheter un, car c’est obligatoire"},{"id":"d","texte":"Rien de grave : ce n’est pas obligatoire d’en apporter"}],"multiple":false}]}$ex$::jsonb,
