   $ex${"titre":"Un camp de natation au bord du lac","competence":"analyser-document","situation":"Tom est en camp de natation au bord d’un lac. Il écrit à son père, et son moniteur note ses progrès.","documents":[{"id":"lac","type":"dialogue","modele":"sms","titre":"Messages de Tom à Dad","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Dad","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Hi Dad! From my window I can see the sea and I can hear the waves."},{"qui":"Tom","texte":"Yesterday the lake was very cold, but I was able to swim 100 metres!"},{"qui":"Tom","texte":"Could you send me my goggles, please?"}],"source":"Messages écrits pour l’exercice"},{"id":"tests","type":"tableau","titre":"Tom’s swimming test","colonnes":["Week","Distance"],"lignes":[["Week 1","25 m"],["Week 2","50 m"],["Week 3","100 m"]],"source":"Résultats inventés pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes de perception** que Tom emploie avec *can*.","aide":"Ce sont des verbes qui parlent de ce qu’on voit et de ce qu’on entend.","type":"zone","document":"lac","multiple":true},{"enonce":"Pourquoi Tom écrit-il « **Could** you send me… » et non « Can you… » ?","aide":"Pense à la manière de demander gentiment un service.","type":"choix","options":[{"id":"a","texte":"Could rend la demande plus polie"},{"id":"b","texte":"Could exprime une réussite précise"},{"id":"c","texte":"Can n’existe pas dans les questions"},{"id":"d","texte":"Could parle d’une action déjà terminée"}],"multiple":false},{"enonce":"D’après le tableau, **de combien de mètres** Tom a-t-il progressé entre la semaine 1 et la semaine 3 ?","aide":"Soustrais la première distance à la dernière.","type":"nombre","unite":"m"},{"enonce":"En semaine 3, Tom a réussi son test (une réussite précise). Complète.","aide":"C’est une réussite ponctuelle, au passé.","type":"trous","segments":["In week 3, Tom ",0," swim 100 m."],"banque":["must","will be able to","was able to","can"]},{"enonce":"Remets en ordre : « Tu pourras peut-être venir. » La phrase commence par You.","aide":"Après might, on emploie be able to.","type":"ordre","items":[{"id":"a","texte":"be"},{"id":"b","texte":"to"},{"id":"c","texte":"You"},{"id":"d","texte":"might"},{"id":"e","texte":"able"},{"id":"f","texte":"come"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m13"]},"explication":"**see** et **hear** : avec les verbes de perception, l’anglais emploie *can*, là où le français dit simplement « je vois, j’entends »."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Could you…?** est une formule plus polie que *Can you…?*."},{"cle":{"type":"nombre","valeur":75,"tolerance":0},"affichage":"75 m","explication":"100 − 25 = **75** mètres de progrès."},{"cle":{"type":"trous","trous":[["was able to"]]},"affichage":"was able to","explication":"**was able to** : réussite ponctuelle au passé."},{"cle":{"type":"ordre","ids":["c","d","a","e","b","f"]},"explication":"**You might be able to come.** Après un modal, on emploie la forme de remplacement *be able to*."}]$ex$::jsonb),
  ('be1d4915-6dbd-5fe9-8eb2-ee28dd76aaa4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les règles de la bibliothèque","competence":"comprendre-langue","situation":"Lina vient d’être inscrite à la bibliothèque de son collège. Elle lit l’affiche des règles avant d’emprunter son premier livre.","documents":[{"id":"regles","type":"fiche","modele":"affiche","entete":"School library rules","sousTitre":"Open every day","emoji":"📚","lignes":[{"texte":"You can borrow three books for two weeks.","id":"z1"},{"texte":"You can’t eat or drink in the library.","id":"z2"},{"texte":"Students may use the computers for homework.","id":"z3"},{"texte":"You mustn’t shout.","id":"z4"}],"pied":"Thank you!","teinte":"violet","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la règle qui dit que Lina **a le droit d’emprunter** des livres.","aide":"Cherche la phrase affirmative avec *borrow*.","type":"zone","document":"regles","multiple":false},{"enonce":"Que veut dire la règle « You can’t eat or drink in the library » ?","aide":"La forme négative de *can* refuse la permission.","type":"choix","options":[{"id":"a","texte":"Tu devrais éviter de boire"},{"id":"b","texte":"Tu es capable de ne pas manger"},{"id":"c","texte":"Tu peux manger si tu veux"},{"id":"d","texte":"C’est interdit de manger ou de boire"}],"multiple":false},{"enonce":"Range chaque demande selon son niveau de politesse.","aide":"*Can* est le plus courant, *may* le plus solennel.","type":"categories","categories":[{"id":"c0","texte":"Familier"},{"id":"c1","texte":"Poli"},{"id":"c2","texte":"Formel"}],"items":[{"id":"i0","texte":"Could I borrow your pen?"},{"id":"i1","texte":"May I come in?"},{"id":"i2","texte":"Can I sit here?"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**You can borrow three books** : *can* accorde la permission, de façon courante."},{"cle":{"type":"choix","ids":["d"]},"explication":"**C’est interdit** : *can’t* exprime l’interdiction."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c0"}},"explication":"**Can** est familier, **could** est poli, **may** est formel : plus on monte, plus on est respectueux."}]$ex$::jsonb),
  ('be1d4915-6dbd-5fe9-8eb2-ee28dd76aaa4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un concert très surveillé","competence":"manier-langue","situation":"Eva raconte à son ami Ben le concert auquel elle est allée la semaine dernière. Ses parents lui ont fixé des règles.","documents":[{"id":"conv","type":"dialogue","modele":"sms","titre":"Messages d’Eva et Ben","participants":[{"nom":"Ben","emoji":"👦","cote":"gauche"},{"nom":"Eva","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Were you allowed to go to the concert last week?"},{"qui":"Eva","texte":"Yes, I was allowed to go! But I wasn’t allowed to stay late."},{"qui":"Ben","texte":"Lucky you! We will be allowed to go to the next one on our own."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre qu’Eva **n’avait pas** la permission de rester tard.","aide":"Cherche la forme négative de *was*.","type":"zone","document":"conv","multiple":false},{"enonce":"Complète avec la bonne forme de *be*.","aide":"*We* est un pluriel, et *last year* est au passé.","type":"trous","segments":["Last year, we ",0," allowed to wear our own clothes."],"banque":["were","are","be","was"]},{"enonce":"Hier, la prof a donné à Lola la permission de partir plus tôt. Quelle phrase est correcte ?","aide":"Pour une permission au passé, on ne garde pas *can* ni *may*.","type":"choix","options":[{"id":"a","texte":"I was allowed to leave early."},{"id":"b","texte":"I can leave early yesterday."},{"id":"c","texte":"I am allowed leave early yesterday."},{"id":"d","texte":"I may leave early yesterday."}],"multiple":false},{"enonce":"Remets en ordre : « Nous aurons le droit d’utiliser des téléphones ». La phrase commence par We.","aide":"Au futur : will + be allowed to.","type":"ordre","items":[{"id":"a","texte":"phones"},{"id":"b","texte":"to"},{"id":"c","texte":"be"},{"id":"d","texte":"will"},{"id":"e","texte":"use"},{"id":"f","texte":"allowed"},{"id":"g","texte":"We"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"**wasn’t** : *wasn’t allowed to* exprime la permission refusée au passé."},{"cle":{"type":"trous","trous":[["were"]]},"affichage":"were","explication":"**were** : *be allowed to* se met au prétérit (*we were allowed to*) pour parler d’une permission passée."},{"cle":{"type":"choix","ids":["a"]},"explication":"**I was allowed to leave early.** *Be allowed to* se conjugue à tous les temps."},{"cle":{"type":"ordre","ids":["g","d","c","f","b","e","a"]},"explication":"**We will be allowed to use phones** : will + be + allowed to + verbe."}]$ex$::jsonb),
  ('be1d4915-6dbd-5fe9-8eb2-ee28dd76aaa4'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les règles de l’auberge de jeunesse","competence":"argumenter","situation":"Lou passe quelques jours dans une auberge de jeunesse en Écosse. Il lit le règlement, puis envoie un message au gérant.","documents":[{"id":"reglement","type":"texte","genre":"article","titre":"House rules","blocs":["Guests may use the kitchen until 9 p.m. Visitors may not enter the bedrooms.","Last summer, guests were allowed to swim in the lake, but this year it is closed. You mustn’t light fires in the garden."],"source":"Règlement écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Lou et du gérant","participants":[{"nom":"Lou","emoji":"🧑","cote":"gauche"},{"nom":"Gérant","emoji":"🧔","cote":"droite"}],"repliques":[{"qui":"Lou","texte":"Could I use the kitchen at 10 p.m.?"},{"qui":"Gérant","texte":"Sorry, you can’t. It closes at nine."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui forment le refus **formel** du règlement.","aide":"C’est le modal le plus poli, suivi de *not*.","type":"zone","document":"reglement","multiple":true},{"enonce":"Touche le mot par lequel le gérant **refuse** la demande de Lou.","aide":"Il refuse de façon courante, pas formelle.","type":"zone","document":"sms","multiple":false},{"enonce":"Lou voudrait cuisiner à 22 h. Que dit le règlement ?","aide":"Relis la première phrase du règlement.","type":"choix","options":[{"id":"a","texte":"Oui : tout est permis la nuit"},{"id":"b","texte":"Oui, avec un adulte"},{"id":"c","texte":"Non : les invités ne peuvent jamais cuisiner"},{"id":"d","texte":"Non : la cuisine ferme à 21 h"}],"multiple":false},{"enonce":"Complète pour dire que les clients avaient le droit de nager l’été dernier.","aide":"Il faut *be allowed to* au passé : le sujet est *guests*.","type":"trous","segments":["Last summer, guests ",0," ",1," to swim in the lake."],"banque":["were","allow","was","allowed"]},{"enonce":"Associe chaque phrase à sa fonction.","aide":"*Mustn’t* est plus fort que *can’t*.","type":"association","gauche":[{"id":"g0","texte":"You mustn’t light fires."},{"id":"g1","texte":"Visitors may not enter."},{"id":"g2","texte":"Could I use the kitchen?"},{"id":"g3","texte":"I was allowed to swim."}],"droite":[{"id":"d0","texte":"Interdiction forte"},{"id":"d1","texte":"Refus formel d’un règlement"},{"id":"d2","texte":"Permission au passé"},{"id":"d3","texte":"Demande polie"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m11"]},"explication":"**may not** : formule des règlements écrits, plus formelle que *can’t*."},{"cle":{"type":"zone","ids":["m11"]},"explication":"**can’t** : refus courant de la permission."},{"cle":{"type":"choix","ids":["d"]},"explication":"**La cuisine ferme à 21 h** : *Guests may use the kitchen until 9 p.m.*"},{"cle":{"type":"trous","trous":[["were"],["allowed"]]},"affichage":"were · allowed","explication":"**were allowed** : on conjugue *be* au prétérit, puis *allowed to*."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"*Mustn’t* interdit fortement ; *may not* est la forme formelle des règlements ; *could* demande poliment ; *was allowed to* parle du passé."}]$ex$::jsonb),
