   $ex$[{"cle":{"type":"zone","ids":["m8","m9"]},"explication":"**should have** + participe passé : un reproche ou un regret sur le passé."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"*Should* conseille, *had better* presse en menaçant un peu, *must* oblige."},{"cle":{"type":"trous","trous":[["shouldn t"]]},"affichage":"shouldn’t","explication":"**shouldn’t have** + participe passé : « je n’aurais pas dû »."},{"cle":{"type":"choix","ids":["c"]},"explication":"**You’d better hurry** : *had better* + base verbale, sans *to*."}]$ex$::jsonb),
  ('02d9bc22-41f8-5ac3-9908-5754e0eafb59'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un contrôle lundi","competence":"argumenter","situation":"Sam est inquiet pour son contrôle d’anglais de lundi. Il écrit à son amie Kim, qui lui répond.","documents":[{"id":"sam","type":"texte","genre":"lettre","titre":"L’e-mail de Sam","blocs":["Dear Kim, I’m nervous about my English test on Monday. I haven’t revised much and I played video games all weekend. What do you think I should do? — Sam"],"source":"E-mail écrit pour l’exercice"},{"id":"kim","type":"texte","genre":"lettre","titre":"La réponse de Kim","blocs":["Hi Sam, You should start now! You’d better not stay up too late, though. If I were you, I’d make a list of the verbs. Why don’t you ask Mr Brown for help? You should have started earlier, but it’s not too late."],"source":"E-mail écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois mots** qui forment le conseil sous forme de **question**.","aide":"Cette tournure commence par *Why*.","type":"zone","document":"kim","multiple":true},{"enonce":"Quelle phrase de Kim est un **regret** sur le passé ?","aide":"Cherche *should* suivi de *have*.","type":"choix","options":[{"id":"a","texte":"If I were you, I’d make a list."},{"id":"b","texte":"You’d better not stay up too late."},{"id":"c","texte":"You should have started earlier."},{"id":"d","texte":"Why don’t you ask Mr Brown?"}],"multiple":false},{"enonce":"Sam regrette d’avoir joué tout le week-end.","aide":"Il n’aurait pas dû faire cela.","type":"trous","segments":["I ",0," have played so much."],"banque":["shouldn’t","don’t","didn’t","should"]},{"enonce":"Associe chaque tournure à son rôle.","aide":"Lis le rôle comme un coup de pouce.","type":"association","gauche":[{"id":"g0","texte":"Why don’t you…?"},{"id":"g1","texte":"If I were you, I’d…"},{"id":"g2","texte":"You should have…"},{"id":"g3","texte":"You’d better not…"}],"droite":[{"id":"d0","texte":"Reproche sur le passé"},{"id":"d1","texte":"Conseil en question"},{"id":"d2","texte":"On se met à la place de l’autre"},{"id":"d3","texte":"Conseil pressant négatif"}]},{"enonce":"Remets en ordre : « Tu ferais mieux de ne pas oublier ton livre ». La phrase commence par You’d.","aide":"*Not* se place après *better*.","type":"ordre","items":[{"id":"a","texte":"not"},{"id":"b","texte":"book"},{"id":"c","texte":"You’d"},{"id":"d","texte":"your"},{"id":"e","texte":"forget"},{"id":"f","texte":"better"}]}]}$ex$::jsonb,
