   $ex${"titre":"Une sortie qui a mal tourné","competence":"argumenter","situation":"Chloé a fait une randonnée sous la pluie. Elle écrit un e-mail à son père, qui lui répond par message.","documents":[{"id":"chloe","type":"texte","genre":"lettre","titre":"L’e-mail de Chloé","blocs":["Dear Dad, I’m wet and cold. I wish I had taken my umbrella. If only I had listened to you! I regret leaving my phone at home. I should have checked the weather."],"source":"E-mail écrit pour l’exercice"},{"id":"papa","type":"dialogue","modele":"sms","titre":"Le message du père","participants":[{"nom":"Chloé","emoji":"👧","cote":"gauche"},{"nom":"Papa","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Papa","texte":"I wish you would call me when you’re late! Would you like a lift home?"}],"source":"Message écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui renforcent le regret de Chloé.","aide":"Ils ouvrent une phrase exclamative.","type":"zone","document":"chloe","multiple":true},{"enonce":"Touche le verbe **en -ING** qui suit *regret*.","aide":"Il est tout près de *my phone*.","type":"zone","document":"chloe","multiple":false},{"enonce":"Quelle phrase veut dire « Je regrette d’avoir laissé mon téléphone » ?","aide":"*Regret* est suivi du verbe en -ING.","type":"choix","options":[{"id":"a","texte":"I regret leave my phone at home."},{"id":"b","texte":"I regret to leaving my phone at home."},{"id":"c","texte":"I regret leaving my phone at home."},{"id":"d","texte":"I regret that leaving my phone at home."}],"multiple":false},{"enonce":"Complète la demande du père.","aide":"Il souhaite que Chloé change son comportement.","type":"trous","segments":["I wish you ",0," call me when you’re late!"],"banque":["can","to","will","would"]},{"enonce":"Associe chaque phrase à sa nuance.","aide":"Pense au rôle de chaque phrase.","type":"association","gauche":[{"id":"g0","texte":"Would you like a lift?"},{"id":"g1","texte":"If only I had listened!"},{"id":"g2","texte":"I wish you a happy birthday."},{"id":"g3","texte":"I should have checked."}],"droite":[{"id":"d0","texte":"Reproche à soi-même"},{"id":"d1","texte":"Vœu sans recul du temps"},{"id":"d2","texte":"Regret fort sur le passé"},{"id":"d3","texte":"Offre polie"}]}]}$ex$::jsonb,
