   $ex${"titre":"Où est Leo ?","competence":"comprendre-langue","situation":"Leo n’est pas en classe ce matin. Max et Anna se demandent pourquoi, en envoyant des messages.","documents":[{"id":"msg","type":"dialogue","modele":"sms","titre":"Messages de Max et Anna","participants":[{"nom":"Max","emoji":"👦","cote":"gauche"},{"nom":"Anna","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Max","texte":"Leo isn’t in class. He might be ill."},{"qui":"Anna","texte":"He must be ill! He was coughing yesterday."},{"qui":"Max","texte":"Or he may be late. The bus is slow."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le modal par lequel Anna se dit **presque sûre** de la cause.","aide":"Elle ne dit pas « peut-être » mais « sûrement ».","type":"zone","document":"msg","multiple":false},{"enonce":"Associe chaque modal à son degré de certitude.","aide":"Du plus sûr au moins sûr, puis le contraire.","type":"association","gauche":[{"id":"g0","texte":"must"},{"id":"g1","texte":"might"},{"id":"g2","texte":"can’t"}],"droite":[{"id":"d0","texte":"Simplement possible"},{"id":"d1","texte":"Presque certain"},{"id":"d2","texte":"Impossible"}]},{"enonce":"Que veut dire « He can’t be at home » ?","aide":"Ici, *can’t* dit que c’est impossible.","type":"choix","options":[{"id":"a","texte":"Il ne peut pas être chez lui"},{"id":"b","texte":"Il n’a pas le droit d’être chez lui"},{"id":"c","texte":"Il ne sait pas être chez lui"},{"id":"d","texte":"Il ne doit pas rentrer chez lui"}],"multiple":false}]}$ex$::jsonb,
