1","texte":"They can’t have arrived yet."},{"id":"g2","texte":"She may have forgotten."},{"id":"g3","texte":"You should have called."}],"droite":[{"id":"d0","texte":"Elle a peut-être oublié"},{"id":"d1","texte":"Tu aurais dû appeler"},{"id":"d2","texte":"Il a dû rater le train"},{"id":"d3","texte":"Ils ne peuvent pas être déjà arrivés"}]}]}$ex$::jsonb,
