   $ex${"titre":"Une journée chez l’oncle coiffeur","competence":"argumenter","situation":"Sam a passé un samedi dans le salon de coiffure de son oncle. Il écrit un e-mail à sa grand-mère, puis discute avec son ami Luc.","documents":[{"id":"sam","type":"texte","genre":"lettre","titre":"L’e-mail de Sam","blocs":["Dear Gran, My uncle got me to help in his shop on Saturday. He made me sweep the floor all morning. I was made to wear a funny apron! Afterwards, I had my hair cut for free."],"source":"E-mail écrit pour l’exercice"},{"id":"luc","type":"dialogue","modele":"sms","titre":"Messages de Luc et Sam","participants":[{"nom":"Luc","emoji":"👦","cote":"gauche"},{"nom":"Sam","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Luc","texte":"Did your uncle let you cut hair?"},{"qui":"Sam","texte":"No! He didn’t let me touch the scissors."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre le **passif** de *make*. Après lui, *to* réapparaît.","aide":"Cherche *I was … to wear*.","type":"zone","document":"sam","multiple":false},{"enonce":"Pourquoi écrit-on « I was made to wear » mais « He made me sweep » ?","aide":"Compare la voix active et la voix passive.","type":"choix","options":[{"id":"a","texte":"Parce que sweep est un verbe d’état"},{"id":"b","texte":"Parce que was est un modal"},{"id":"c","texte":"Au passif, make est suivi de to"},{"id":"d","texte":"Parce que wear est irrégulier"}],"multiple":false},{"enonce":"Complète pour dire « Il ne m’a pas laissé toucher les ciseaux ».","aide":"Il s’agit d’une permission refusée.","type":"trous","segments":["He didn’t ",0," me touch the scissors."],"banque":["let","have","get","make"]},{"enonce":"Associe chaque phrase française à sa traduction.","aide":"Choisis le verbe : obliger, faire faire, autoriser, convaincre.","type":"association","gauche":[{"id":"g0","texte":"Il m’a fait attendre."},{"id":"g1","texte":"Je me suis fait couper les cheveux."},{"id":"g2","texte":"Il m’a laissé sortir."},{"id":"g3","texte":"J’ai réussi à le convaincre de venir."}],"droite":[{"id":"d0","texte":"I got him to come."},{"id":"d1","texte":"He made me wait."},{"id":"d2","texte":"He let me go out."},{"id":"d3","texte":"I had my hair cut."}]},{"enonce":"Remets en ordre : « Mon oncle m’a convaincu de l’aider ». La phrase commence par My.","aide":"*Get* + complément + *to* + verbe.","type":"ordre","items":[{"id":"a","texte":"My"},{"id":"b","texte":"him"},{"id":"c","texte":"me"},{"id":"d","texte":"uncle"},{"id":"e","texte":"got"},{"id":"f","texte":"help"},{"id":"g","texte":"to"}]}]}$ex$::jsonb,
