   $ex${"titre":"Une semaine au camp d’été","competence":"argumenter","situation":"Sara écrit à sa grand-mère depuis un camp au bord d’un lac. Celle-ci lui répond par message.","documents":[{"id":"sara","type":"texte","genre":"lettre","titre":"L’e-mail de Sara","blocs":["Dear Gran, We got up at six today. I’m looking forward to the lake trip! We ran out of bread, so Tom went to find some. Yesterday I nearly gave up because the hill was steep, but I carried on. Love, Sara"],"source":"E-mail écrit pour l’exercice"},{"id":"gran","type":"dialogue","modele":"sms","titre":"Messages de Gran","participants":[{"nom":"Gran","emoji":"👵","cote":"gauche"},{"nom":"Sara","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Gran","texte":"Look after your little cousin! Don’t forget to put on sun cream. What did you find out about the bears?"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui veulent dire « continuer ».","aide":"Cherche un verbe suivi de *on*.","type":"zone","document":"sara","multiple":true},{"enonce":"Que veut dire « We ran out of bread » ?","aide":"*Run out of* parle de quelque chose qui s’épuise.","type":"choix","options":[{"id":"a","texte":"Nous avons jeté le pain"},{"id":"b","texte":"Nous avons couru acheter du pain"},{"id":"c","texte":"Nous n’avions plus de pain"},{"id":"d","texte":"Nous avons mangé tout le pain"}],"multiple":false},{"enonce":"Touche les **deux mots** du verbe qui veut dire « s’occuper de ».","aide":"C’est le premier verbe du message.","type":"zone","document":"gran","multiple":true},{"enonce":"Associe chaque verbe à son sens.","aide":"Pense au sens complet, pas mot à mot.","type":"association","gauche":[{"id":"g0","texte":"find out"},{"id":"g1","texte":"give up"},{"id":"g2","texte":"take off"},{"id":"g3","texte":"grow up"}],"droite":[{"id":"d0","texte":"Enlever"},{"id":"d1","texte":"Grandir"},{"id":"d2","texte":"Découvrir"},{"id":"d3","texte":"Abandonner"}]},{"enonce":"Remets en ordre : « Éteins-le, s’il te plaît ». La phrase commence par Please.","aide":"Le pronom se place avant la particule.","type":"ordre","items":[{"id":"a","texte":"Please"},{"id":"b","texte":"it"},{"id":"c","texte":"off"},{"id":"d","texte":"turn"}]}]}$ex$::jsonb,
